payload.arguments:
{"command":"@'
$json = Get-Content 'reports/01-inventory.json' -Raw | ConvertFrom-Json
$subvaultRoots = @($json.subvaults_detected | ForEach-Object { $_.path })
$badNames = @($json.bad_name_files)
$trashDirs = @($json.trash_directories)
$mirrorAreas = @($json.mirror_or_import_areas)

$genericPattern = '(?i)(^|\\)(untitled(?: \d+)?|sem t[ií]tulo(?: \d+)?|novo(?: \d+)?|rascunho|00_rascunho)(\.[^\\]+)?$'
$importPathPattern = '(?i)(dados brutos|todas as notas|\\arquivos\\|\\arquivos$|\\arquivos de apoio\\|import|backup|export)'

$candidates = New-Object System.Collections.Generic.List[object]

foreach ($area in $mirrorAreas) {
  $path = $area.path
  if ($path -eq 'Google Drive (Not synced)') {
    $isSubvault = $subvaultRoots | Where-Object { $_ -like "$path*" -and $_ -ne '.' }
    $candidates.Add([pscustomobject]@{
      kind = 'folder'; path = $path; source_category = 'Google Drive (Not synced)';
      file_count = $area.file_count; seems_like = @('espelho','import', $(if($isSubvault){'sub-vault'}));
      risk = if ($isSubvault) { 'medium' } else { 'low' };
      reason = 'Area de Google Drive nao sincronizado com forte sinal de espelho/import dentro do vault.';
      recommendation = if ($isSubvault) { 'Preparar manifesto por subarvore e revisar separadamente qualquer sub-vault antes de quarentena.' } else { 'Priorizar manifesto de quarentena por pasta, sem mover ate revisao humana.' }
    })
  }
  elseif ($path -like 'HOME\\Clones*') {
    $candidates.Add([pscustomobject]@{
      kind = 'folder'; path = $path; source_category = 'Clones'; file_count = $area.file_count;
      seems_like = @('espelho','lixo'); risk = 'low';
      reason = 'Pasta de clones com alta chance de copias de trabalho ou espelhos redundantes.';
      recommendation = 'Preparar manifesto de quarentena por pasta; validar se algum clone ainda e ambiente ativo antes de mover.'
    })
  }
  elseif ($path -match '(?i)\\arquivos$' -or $path -match '(?i)\\ARQUIVOS$') {
    $nested = $subvaultRoots | Where-Object { $_ -like "$path*" -and $_ -ne '.' }
    $candidates.Add([pscustomobject]@{
      kind = 'folder'; path = $path; source_category = 'import'; file_count = $area.file_count;
      seems_like = @('import', $(if($nested){'sub-vault'})); risk = if ($nested){'medium'}else{'low'};
      reason = 'Nome de pasta sugere deposito de anexos/importacao, com baixa centralidade para navegacao do vault.';
      recommendation = 'Revisar amostra curta e, se confirmado como importacao auxiliar, colocar em manifesto de quarentena por pasta.'
    })
  }
}

foreach ($dir in $trashDirs) {
  $isSubvault = $subvaultRoots | Where-Object { $_ -like "$($dir.path)*" -and $_ -ne '.' }
  $candidates.Add([pscustomobject]@{
    kind = 'folder'; path = $dir.path; source_category = '.trash'; file_count = $dir.file_count;
    seems_like = @('lixo', $(if($isSubvault){'sub-vault'})); risk = if ($isSubvault) { 'medium' } else { 'low' };
    reason = 'Conteudo em pasta .trash, com forte indicio de descarte ou resquicio de importacao.';
    recommendation = if ($isSubvault) { 'Nao mover em lote antes de revisar o sub-vault de origem; preparar manifesto separado.' } else { 'Candidato forte para quarentena por pasta inteira apos revisao humana rapida.' }
  })
}

foreach ($file in $badNames) {
  $path = $file.path
  $leaf = Split-Path $path -Leaf
  $tags = New-Object System.Collections.Generic.List[string]
  $reasons = New-Object System.Collections.Generic.List[string]
  $risk = 'low'

  if ($path -match '(?i)^Google Drive \(Not synced\)') { $tags.Add('espelho'); $tags.Add('import'); $reasons.Add('Arquivo em area de Google Drive nao sincronizado.') }
  if ($path -match '(?i)\\\.trash(\\|$)') { $tags.Add('lixo'); $reasons.Add('Arquivo dentro de .trash.') }
  if ($leaf -match '(?i)^00_rascunho\.md$') { $tags.Add('rascunho'); $reasons.Add('Nome de rascunho explicito.') }
  elseif ($leaf -match '(?i)^(untitled(?: \d+)?|sem t[ií]tulo(?: \d+)?|novo(?: \d+)?)') { $tags.Add('rascunho'); $reasons.Add('Nome generico sem identificacao semantica.') }
  if ($path -match $importPathPattern) { if (-not $tags.Contains('import')) { $tags.Add('import') }; $reasons.Add('Caminho sugere lote importado ou deposito bruto.') }
  if ($file.in_nested_subvault) { $tags.Add('sub-vault'); $risk = 'medium'; $reasons.Add('Arquivo dentro de sub-vault detectado.') }

  if ($tags.Count -gt 0) {
    $candidates.Add([pscustomobject]@{
      kind = 'file'; path = $path; source_category = 'generic-name'; file_count = 1; size = $file.size;
      seems_like = @($tags | Select-Object -Unique); risk = $risk;
      reason = ($reasons | Select-Object -Unique) -join ' ';
      recommendation = if ($risk -eq 'medium') { 'Revisar no contexto do sub-vault antes de incluir em manifesto.' } elseif ($path -match '(?i)\\\.trash(\\|$)' -and $file.size -eq 0) { 'Candidato forte para manifesto de quarentena; arquivo vazio e generico em .trash.' } elseif ($file.size -eq 0) { 'Candidato de baixo risco para manifesto individual de quarentena.' } else { 'Revisar rapidamente o conteudo e, se continuar sem funcao clara, incluir em manifesto individual.' }
    })
  }
}

$candidates = $candidates | Sort-Object kind, path -Unique
$candidates | Group-Object source_category | Select-Object Name,Count | ConvertTo-Json -Depth 5
'@ | powershell -NoProfile -Command -","workdir":"C:\Users\Kevyn Lucas\Documents\Codex Kevyn","timeout_ms":30000}

